package com.ecole.gestion_scolaire.hr.controller; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.enums.*; import com.ecole.gestion_scolaire.hr.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/hr/teachers") public class TeacherController { private final TeacherService service; public TeacherController(TeacherService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('ENSEIGNANT_CONSULTER')") public List<TeacherResponse> all(){return service.all();} @GetMapping("/{id}") @PreAuthorize("hasAuthority('ENSEIGNANT_CONSULTER')") public TeacherResponse one(@PathVariable Long id){return service.one(id);} @PostMapping @PreAuthorize("hasAuthority('ENSEIGNANT_CREER')") public ResponseEntity<TeacherResponse> create(@Valid @RequestBody TeacherRequest q){return ResponseEntity.status(201).body(service.create(q));} @PatchMapping("/{id}/status/{status}") @PreAuthorize("hasAuthority('ENSEIGNANT_MODIFIER')") public TeacherResponse status(@PathVariable Long id,@PathVariable TeacherStatus status){return service.status(id,status);} @PostMapping("/{id}/subjects/{subjectId}") @PreAuthorize("hasAuthority('ENSEIGNANT_AFFECTER')") public void addSubject(@PathVariable Long id,@PathVariable Long subjectId){service.addSubject(id,subjectId);} @DeleteMapping("/{id}/subjects/{subjectId}") @PreAuthorize("hasAuthority('ENSEIGNANT_AFFECTER')") public void removeSubject(@PathVariable Long id,@PathVariable Long subjectId){service.removeSubject(id,subjectId);} }